#!/usr/bin/env python3
"""Verify the `cardano-init doctor` install recipes actually work.

Given ONE installer key (e.g. "apt"), this reads `registry/deps.toml`, finds
every dependency whose recipe offers a method for that installer, runs the
rendered install command, and asserts the dep's declared `binaries` land on
PATH afterwards. Exits non-zero if any recipe fails to install or leaves its
binary unreachable.

This is the real-world half of the two-tier installer gate: the PR gate
(`cargo test`, via `src/doctor/catalog.rs`) already proves every recipe parses
and names a known installer. What it CANNOT prove is that the recipe still
works against the live world — a renamed apt package, a moved aikup npm path, a
brew formula rename. That is external drift, so it belongs on a schedule, not a
PR gate (same rationale as tool-smoke.yml).

This file is also the single source of truth for WHICH installers the gate
covers (`TESTED`) and which it deliberately doesn't (`EXCLUDED`, with a
reason). The workflow matrix and the "Tested install commands" table in the
docs are both generated from it, and `--check` fails if `deps.toml` uses an
installer that is in neither list, so coverage can't silently shrink.

Usage:
    verify_installers.py <installer-key> [--deps <path>]   run one installer's recipes
    verify_installers.py --matrix                          print the workflow matrix (JSON)
    verify_installers.py --docs                            regenerate the docs table
    verify_installers.py --check                           coverage + docs drift check (CI)
    verify_installers.py --scope                           write the run's scope to the job summary

Requires Python 3.11+ (uses the stdlib `tomllib`), present on all runners and
container images the workflow targets.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEPS_FILE = ROOT / "registry" / "deps.toml"
DOC_FILE = ROOT / "docs" / "user-guide" / "commands.md"
DOC_START = "<!-- installer-coverage:start (generated by .github/scripts/verify_installers.py) -->"
DOC_END = "<!-- installer-coverage:end -->"

# ---------------------------------------------------------------------------
# Command templates.
#
# MUST stay in lockstep with `Installer::command()` in
# src/doctor/installers.rs — that function is the single source of truth for
# what `cardano-init doctor` tells a user to run; this table mirrors it so the
# workflow exercises the exact same commands. `{arg}` is the recipe's arg (a
# package name, an installer-script URL, or a target, per installer).
# ---------------------------------------------------------------------------
COMMANDS: dict[str, str] = {
    "brew": "brew install {arg}",
    "apt": "sudo apt install -y {arg}",
    "dnf": "sudo dnf install -y {arg}",
    "pacman": "sudo pacman -S --noconfirm {arg}",
    "winget": "winget install {arg}",
    "nix": "nix profile install nixpkgs#{arg}",
    "go": "go install {arg}",
    "cargo": "cargo install {arg}",
    "npm": "npm install -g {arg}",
    "aikup": "aikup install {arg}",
    "cardano-up": "cardano-up install {arg}",
    "tx3up": "tx3up install {arg}",
    "curl": "curl -sSfL {arg} | sh",
    "powershell": 'powershell -c "irm {arg} | iex"',
}

# ---------------------------------------------------------------------------
# Coverage.
#
# TESTED: installer → where the workflow runs it. `platform` is what the docs
# table and job summary show; `runs-on`/`container` feed the workflow matrix.
# A `container` gives a clean image, which matters for installers whose tools
# GitHub's hosted images already ship (a preinstalled binary would make the
# presence check pass without proving anything).
#
# EXCLUDED: installer → why it isn't run. Installers that no recipe uses
# (today dnf, pacman, cardano-up) need no entry: there is nothing to verify.
# ---------------------------------------------------------------------------
UBUNTU_HOST = {"runs-on": "ubuntu-latest", "platform": "Ubuntu (GitHub-hosted runner)"}
UBUNTU_CLEAN = {"runs-on": "ubuntu-latest", "container": "ubuntu:24.04", "platform": "Ubuntu 24.04 (clean container)"}
WINDOWS_HOST = {"runs-on": "windows-latest", "platform": "Windows (GitHub-hosted runner)"}

TESTED: dict[str, dict[str, str]] = {
    "apt": UBUNTU_CLEAN,
    "brew": {"runs-on": "macos-latest", "platform": "macOS (GitHub-hosted runner)"},
    "nix": UBUNTU_HOST,
    "npm": UBUNTU_HOST,
    "cargo": UBUNTU_HOST,
    "go": UBUNTU_HOST,
    "aikup": UBUNTU_HOST,
    "tx3up": UBUNTU_HOST,
    "curl": UBUNTU_CLEAN,
    "winget": WINDOWS_HOST,
    "powershell": WINDOWS_HOST,
}

EXCLUDED: dict[str, str] = {}

# Individual (dep, installer) recipes skipped inside a tested installer, with a
# reason. Shown in the docs table and the job summary like EXCLUDED.
EXCLUDED_RECIPES: dict[tuple[str, str], str] = {}


# ---------------------------------------------------------------------------
# Unattended mode.
#
# Some installer scripts ask a question before installing. The command we run
# stays exactly what `doctor` prints; only the environment around it changes,
# using each installer's own unattended mechanism (same spirit as the nix
# profile redirect and EXTRA_BIN_DIRS below). Keyed by the recipe's arg.
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Unattended:
    note: str
    env: dict[str, str] = field(default_factory=dict)
    # (output regex, reply) pairs answered on a pseudo-terminal, for installers
    # with no environment switch that refuse to run without a terminal.
    answers: tuple[tuple[str, str], ...] = ()


UNATTENDED: dict[str, Unattended] = {
    # ghcup's documented unattended switch.
    "https://get-ghcup.haskell.org": Unattended(
        note="run with `BOOTSTRAP_HASKELL_NONINTERACTIVE=1`, ghcup's unattended mode",
        env={"BOOTSTRAP_HASKELL_NONINTERACTIVE": "1"},
    ),
    # rustup has no environment switch for -y, and exits when there is no
    # terminal. Run it on a pseudo-terminal and take the default (1, proceed).
    "https://sh.rustup.rs": Unattended(
        note="run on a terminal, answering its prompt with the default (proceed with the standard installation)",
        answers=((r"Proceed with standard installation", "\n"),),
    ),
}

# Tool-managed installers drop binaries into their own dir, which their
# interactive installer would add to a shell profile — but CI shells are
# non-interactive, so we augment the lookup PATH with the standard locations.
# (The install itself is unchanged; only our presence check looks wider.)
EXTRA_BIN_DIRS = [
    Path.home() / ".cargo" / "bin",
    Path.home() / ".aiken" / "bin",
    Path.home() / "go" / "bin",
    Path.home() / ".local" / "bin",
    Path.home() / ".ghcup" / "bin",
    # tx3up installs the toolchain (trix/dolos/…) under ~/.tx3/<channel>/bin,
    # with `default` symlinked to the active channel.
    Path.home() / ".tx3" / "default" / "bin",
    Path.home() / ".tx3" / "bin",
    Path("/root/.cargo/bin"),
    Path("/root/.aiken/bin"),
    Path("/root/.tx3/default/bin"),
]


# ---------------------------------------------------------------------------
# Recipes and coverage
# ---------------------------------------------------------------------------
def load_recipes(deps_path: Path = DEPS_FILE) -> dict:
    with deps_path.open("rb") as f:
        return tomllib.load(f)


def all_methods(recipes: dict) -> list[tuple[str, str, str, list[str]]]:
    """(dep_id, installer, arg, binaries) for every install method in deps.toml."""
    out = []
    for dep_id, recipe in recipes.items():
        binaries = recipe.get("binaries", [])
        for entry in recipe.get("install", []):
            # Each entry is a single-key table: { <installer> = "<arg>" }.
            for key, arg in entry.items():
                out.append((dep_id, key, arg, binaries))
    return out


def load_methods(deps_path: Path, installer: str) -> list[tuple[str, str, list[str]]]:
    """Return (dep_id, arg, binaries) for every recipe offering `installer`."""
    return [
        (dep_id, arg, binaries)
        for dep_id, key, arg, binaries in all_methods(load_recipes(deps_path))
        if key == installer
    ]


def coverage_errors(recipes: dict) -> list[str]:
    errors = []
    both = TESTED.keys() & EXCLUDED.keys()
    if both:
        errors.append(f"installer(s) both tested and excluded: {', '.join(sorted(both))}")
    for name in TESTED.keys() | EXCLUDED.keys():
        if name not in COMMANDS:
            errors.append(f"unknown installer '{name}' in TESTED/EXCLUDED")
    used = {key for _, key, _, _ in all_methods(recipes)}
    for name in sorted(used - TESTED.keys() - EXCLUDED.keys()):
        errors.append(
            f"deps.toml uses installer '{name}', which is neither in TESTED nor in "
            "EXCLUDED in .github/scripts/verify_installers.py; add a workflow row "
            "or an exclusion with its reason"
        )
    methods = {(dep, key) for dep, key, _, _ in all_methods(recipes)}
    for dep, key in EXCLUDED_RECIPES:
        if (dep, key) not in methods:
            errors.append(f"EXCLUDED_RECIPES names {dep} via {key}, which deps.toml doesn't offer")
    return errors


def matrix() -> dict:
    rows = []
    for installer, where in TESTED.items():
        rows.append(
            {
                "installer": installer,
                "runs-on": where["runs-on"],
                # Empty for host rows → no container.
                "container": where.get("container", ""),
            }
        )
    return {"include": rows}


# ---------------------------------------------------------------------------
# Docs table and job-summary scope
# ---------------------------------------------------------------------------
def installer_deps(recipes: dict) -> dict[str, list[str]]:
    by_installer: dict[str, list[str]] = {}
    for dep_id, key, _, _ in all_methods(recipes):
        by_installer.setdefault(key, []).append(dep_id)
    return by_installer


def render_docs(recipes: dict) -> str:
    by_installer = installer_deps(recipes)
    lines = [
        "| Installer | Tested on | Dependencies |",
        "|-----------|-----------|--------------|",
    ]
    for installer in sorted(by_installer):
        if installer in EXCLUDED:
            where = f"Not tested: {EXCLUDED[installer]}"
        else:
            where = TESTED[installer]["platform"]
        cells = []
        for dep in by_installer[installer]:
            reason = EXCLUDED_RECIPES.get((dep, installer))
            cells.append(f"{dep} (not tested: {reason})" if reason else dep)
        lines.append(f"| `{installer}` | {where} | {', '.join(cells)} |")
    used_args = {arg for _, key, arg, _ in all_methods(recipes) if key == "curl"}
    notes = [
        f"- `{COMMANDS['curl'].format(arg=arg)}` is {u.note}."
        for arg, u in UNATTENDED.items()
        if arg in used_args
    ]
    if notes:
        lines += [
            "",
            "Some install scripts ask a question before they install anything. "
            "CI runs these commands unchanged and answers as follows:",
            "",
        ]
        lines += notes
    return "\n".join(lines)


def update_docs(check: bool, recipes: dict) -> int:
    doc = DOC_FILE.read_text()
    try:
        head, rest = doc.split(DOC_START, 1)
        _, tail = rest.split(DOC_END, 1)
    except ValueError:
        print(f"{DOC_FILE.relative_to(ROOT)}: missing installer-coverage markers", file=sys.stderr)
        return 1
    updated = f"{head}{DOC_START}\n{render_docs(recipes)}\n{DOC_END}{tail}"
    if check:
        if updated != doc:
            print(
                f"{DOC_FILE.relative_to(ROOT)} is out of date with registry/deps.toml; "
                "run .github/scripts/verify_installers.py --docs",
                file=sys.stderr,
            )
            return 1
        return 0
    DOC_FILE.write_text(updated)
    return 0


def write_summary(text: str) -> None:
    """Append Markdown to the GitHub job summary (stdout when run locally)."""
    path = os.environ.get("GITHUB_STEP_SUMMARY")
    if path:
        with open(path, "a", encoding="utf-8") as f:
            f.write(text + "\n")
    else:
        print(text)


def scope_summary(recipes: dict) -> str:
    """What a green run of the whole workflow does and doesn't cover."""
    by_installer = installer_deps(recipes)
    total = sum(len(v) for v in by_installer.values())
    untested = [(inst, dep, EXCLUDED[inst]) for inst, deps in by_installer.items() if inst in EXCLUDED for dep in deps]
    untested += [(inst, dep, why) for (dep, inst), why in EXCLUDED_RECIPES.items()]
    lines = [
        "## Installer coverage",
        "",
        f"`registry/deps.toml` has {total} install recipes. This run covers "
        f"{total - len(untested)} of them. Each installer is tested on one platform only.",
        "",
        render_docs(recipes),
    ]
    if untested:
        lines += ["", "**Not covered by this run:**", ""]
        lines += [f"- {dep} via `{inst}`: {why}" for inst, dep, why in untested]
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Running a recipe
# ---------------------------------------------------------------------------
def _is_dir(d: Path) -> bool:
    """Like `Path.is_dir()` but treats an unstattable path as absent.

    A candidate we can't reach (e.g. `/root/.cargo/bin` from a non-root runner)
    raises `PermissionError`, which `Path.is_dir()` propagates rather than
    swallowing. For a best-effort PATH-augmentation probe, unreachable == not a
    usable bin dir, so fold every stat error into False.
    """
    try:
        return d.is_dir()
    except OSError:
        return False


def _windows_registry_path() -> list[str]:
    """PATH as the registry now holds it.

    winget and the PowerShell installers add their bin dirs to the user or
    machine PATH in the registry; a new terminal would see them, but this
    process's environment doesn't. Reading the registry is what opening a new
    terminal does.
    """
    if os.name != "nt":
        return []
    import winreg

    parts: list[str] = []
    keys = [
        (winreg.HKEY_LOCAL_MACHINE, r"SYSTEM\CurrentControlSet\Control\Session Manager\Environment"),
        (winreg.HKEY_CURRENT_USER, r"Environment"),
    ]
    for hive, sub in keys:
        try:
            with winreg.OpenKey(hive, sub) as key:
                value, _ = winreg.QueryValueEx(key, "Path")
        except OSError:
            continue
        parts += [os.path.expandvars(p) for p in value.split(os.pathsep) if p]
    return parts


def lookup_path(extra: list[Path] | None = None) -> str:
    """PATH augmented with the tool-managed bin dirs (for the presence check)."""
    parts = os.environ.get("PATH", "").split(os.pathsep)
    parts += _windows_registry_path()
    parts += [str(d) for d in EXTRA_BIN_DIRS if _is_dir(d)]
    parts += [str(d) for d in (extra or []) if _is_dir(d)]
    return os.pathsep.join(parts)


@dataclass
class Plan:
    command: str
    extra_bin_dirs: list[Path]
    # Directory the recipe must install into, when the installer has one
    # (nix's throwaway profile). Proves the recipe, not a preinstalled copy.
    own_bin_dir: Path | None = None
    unattended: Unattended | None = None


def build_command(installer: str, template: str, arg: str) -> tuple[str, list[Path]]:
    """Render a recipe's install command and any extra bin dirs to look in.

    Mirrors `Installer::command()`; `.rstrip()` matches its bare `aikup install`
    (empty arg ⇒ latest, no trailing space).

    For `nix`, each recipe is redirected into its own throwaway profile. A real
    user installs ONE tool, but this gate installs every nix recipe into a
    single environment, where two packages that ship the same file collide
    (e.g. rustup and cargo both provide `cargo.bash`). Per-recipe profiles
    remove that false conflict; the nixpkgs attr installed is exactly what
    `doctor` prints — only the profile location differs, in the same spirit as
    the EXTRA_BIN_DIRS PATH augmentation above.
    """
    command = template.format(arg=arg).rstrip()
    extra: list[Path] = []
    if installer == "nix":
        profile = Path(tempfile.mkdtemp(prefix="nixprof-")) / "profile"
        command = command.replace(
            "nix profile install ",
            f"nix profile install --profile {profile} ",
            1,
        )
        extra.append(profile / "bin")
    return command, extra


def plan(installer: str, arg: str) -> Plan:
    command, extra = build_command(installer, COMMANDS[installer], arg)
    return Plan(
        command=command,
        extra_bin_dirs=extra,
        own_bin_dir=extra[0] if installer == "nix" else None,
        unattended=UNATTENDED.get(arg) if installer == "curl" else None,
    )


def run_on_pty(command: str, env: dict[str, str], answers: tuple[tuple[str, str], ...]) -> int:
    """Run `command` on a pseudo-terminal, replying to each prompt once."""
    import pty

    pending = [(re.compile(pattern), reply) for pattern, reply in answers]
    seen = b""
    pid, fd = pty.fork()
    if pid == 0:  # child
        os.execvpe("sh", ["sh", "-c", command], env)
    while True:
        try:
            chunk = os.read(fd, 4096)
        except OSError:  # EIO: the child closed the terminal
            break
        if not chunk:
            break
        sys.stdout.buffer.write(chunk)
        sys.stdout.flush()
        seen = (seen + chunk)[-8192:]
        text = seen.decode(errors="replace")
        for item in list(pending):
            if item[0].search(text):
                os.write(fd, item[1].encode())
                pending.remove(item)
    _, status = os.waitpid(pid, 0)
    return os.waitstatus_to_exitcode(status)


def run(p: Plan) -> int:
    env = dict(os.environ)
    if p.unattended:
        env.update(p.unattended.env)
        print(f"  (unattended: {p.unattended.note})", flush=True)
        if p.unattended.answers:
            return run_on_pty(p.command, env, p.unattended.answers)
    return subprocess.run(p.command, shell=True, env=env).returncode


def winget_lists(arg: str) -> bool:
    """Whether winget reports the package as installed (proof for winget)."""
    rc = subprocess.run(
        ["winget", "list", "--exact", "--id", arg, "--accept-source-agreements"],
        stdout=subprocess.DEVNULL,
    ).returncode
    return rc == 0


@dataclass
class Result:
    dep_id: str
    command: str
    status: str  # "installed" | "unproven" | "failed"
    detail: str = ""


def verify_one(
    dep_id: str, installer: str, arg: str, binaries: list[str], p: Plan, cache: dict, preexisting: set[str]
) -> Result:
    """Run one install command; report whether its binaries are reachable.

    Success is defined by the binary being reachable afterwards, NOT by the
    install command's exit code. Some recipes exit non-zero for reasons that
    don't reflect a broken recipe — e.g. brew's rustup post-install step fails
    on a runner that already ships a Rust toolchain, yet `rustup` is installed
    and on PATH. We surface a non-zero exit as a warning but only fail when a
    declared binary is actually missing.

    A binary that was already on PATH before the install proves nothing about
    the recipe. Such a recipe passes only with installer-specific proof (the
    binary in nix's throwaway profile, `winget list` finding the package);
    otherwise it is reported as unproven.
    """
    print(f"::group::{dep_id} via {p.command}", flush=True)
    before = preexisting & set(binaries)

    # Two deps can share one recipe (rust and rustup both run sh.rustup.rs);
    # run it once per job, then check each dep's binaries.
    if p.command in cache:
        install_rc = cache[p.command]
        print("  (same command already ran in this job; checking binaries only)", flush=True)
    else:
        install_rc = run(p)
        cache[p.command] = install_rc

    path = lookup_path(p.extra_bin_dirs)
    missing = []
    for binary in binaries:
        if shutil.which(binary, path=path):
            print(f"  ✓ {binary} on PATH", flush=True)
        else:
            print(f"  ✗ {binary} NOT found after install", flush=True)
            missing.append(binary)

    if install_rc != 0:
        if missing:
            print(f"  ✗ install command exited {install_rc}", flush=True)
        else:
            print(
                f"  ! install command exited {install_rc}, but binaries are "
                f"present — treating as OK",
                flush=True,
            )

    result = Result(dep_id, p.command, "installed")
    if missing:
        result.status = "failed"
        result.detail = f"not found after install: {', '.join(missing)}"
    elif p.own_bin_dir is not None:
        if not any(shutil.which(b, path=str(p.own_bin_dir)) for b in binaries):
            result.status = "failed"
            result.detail = f"nothing installed into {p.own_bin_dir}"
    elif installer == "winget":
        if not winget_lists(arg):
            result.status = "failed"
            result.detail = "`winget list` doesn't show the package"
    elif before:
        result.status = "unproven"
        result.detail = f"already on PATH before install: {', '.join(sorted(before))}"
        print(f"::warning::{dep_id} via {installer}: {result.detail}; the recipe isn't proven", flush=True)
    print("::endgroup::", flush=True)
    return result


def verify(installer: str, deps_path: Path) -> int:
    methods = load_methods(deps_path, installer)
    if not methods:
        # An installer with no recipes today (e.g. dnf/pacman currently) is not
        # a failure — it is simply nothing to verify. Logged, never silent.
        print(f"no recipes use '{installer}' — nothing to verify.")
        return 0

    print(f"verifying {len(methods)} recipe(s) for '{installer}':\n")
    results: list[Result] = []
    skipped: list[tuple[str, str]] = []
    cache: dict[str, int] = {}
    # What was on the machine before this job installed anything. Taken once,
    # so a recipe that shares a command with an earlier one (rust and rustup)
    # isn't mistaken for preinstalled.
    path = lookup_path()
    preexisting = {b for _, _, bins in methods for b in bins if shutil.which(b, path=path)}
    for dep_id, arg, binaries in methods:
        reason = EXCLUDED_RECIPES.get((dep_id, installer))
        if reason:
            print(f"skipping {dep_id}: {reason}")
            skipped.append((dep_id, reason))
            continue
        results.append(verify_one(dep_id, installer, arg, binaries, plan(installer, arg), cache, preexisting))

    icon = {"installed": "✅ installed", "unproven": "⚠️ not proven", "failed": "❌ failed"}
    summary = [
        f"## `{installer}` recipes ({TESTED.get(installer, {}).get('platform', 'local run')})",
        "",
        "| Dependency | Command | Result |",
        "|------------|---------|--------|",
    ]
    for r in results:
        detail = f": {r.detail}" if r.detail else ""
        # A pipe ends a table cell even inside backticks.
        command = r.command.replace("|", "\\|")
        summary.append(f"| {r.dep_id} | `{command}` | {icon[r.status]}{detail} |")
    for dep_id, reason in skipped:
        summary.append(f"| {dep_id} | — | not tested: {reason} |")
    write_summary("\n".join(summary))

    failures = [r.dep_id for r in results if r.status == "failed"]
    print()
    if failures:
        print(f"FAILED for '{installer}': {', '.join(failures)}")
        return 1
    unproven = [r.dep_id for r in results if r.status == "unproven"]
    if unproven:
        print(f"OK, but not proven (binary was already on PATH): {', '.join(unproven)}")
    else:
        print(f"OK: all '{installer}' recipes install and expose their binaries.")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("installer", nargs="?", help="installer key, e.g. apt, brew, nix")
    parser.add_argument("--deps", type=Path, default=DEPS_FILE, help="path to registry/deps.toml")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--matrix", action="store_true", help="print the workflow matrix as JSON")
    mode.add_argument("--docs", action="store_true", help="regenerate the docs coverage table")
    mode.add_argument("--check", action="store_true", help="fail on uncovered installers or a stale docs table")
    mode.add_argument("--scope", action="store_true", help="write the run's coverage to the job summary")
    args = parser.parse_args()

    if args.matrix:
        print(json.dumps(matrix()))
        return 0
    if args.docs or args.check or args.scope:
        recipes = load_recipes(args.deps)
        errors = coverage_errors(recipes)
        for e in errors:
            print(e, file=sys.stderr)
        if errors:
            return 1
        if args.scope:
            write_summary(scope_summary(recipes))
            return 0
        return update_docs(args.check, recipes)

    if not args.installer:
        parser.error("give an installer key, or one of --matrix/--docs/--check/--scope")
    if args.installer not in COMMANDS:
        print(f"unknown installer '{args.installer}'", file=sys.stderr)
        return 2
    return verify(args.installer, args.deps)


if __name__ == "__main__":
    sys.exit(main())
